import random
S,E=4302,42701; delta=600
def reach(ev, src, tgt):
    ev=sorted(ev,key=lambda x:x[2])
    inf={src:[S-1]}
    for u,v,t in ev:
        if u in inf:
            b=None
            for tu in reversed(inf[u]):
                if tu<=t: b=tu; break
            if b is not None and (u==src or t-b<=delta):
                if v not in inf: inf[v]=[t]
                elif inf[v][-1]!=t: inf[v].append(t)
    return tgt in inf, len(inf)
base=[(u,v,t) for u,v,t in events if S<=t<=E]
