# null: reshuffle timestamps among the same edges within window (preserves structure & volume & degrees)
random.seed(0)
times=[t for _,_,t in base]
hits=0;N=300;sizes=[]
for _ in range(N):
    tt=times[:]; random.shuffle(tt)
    sh=[(u,v,tt[i]) for i,(u,v,_) in enumerate(base)]
    r,s=reach(sh,798,131); hits+=r; sizes.append(s)
print("null hit rate",hits/N,"mean reach size",sum(sizes)/N)

